import csv
events=[]
class Sink:
 def write(self,text):
  events.append('write:'+text)
  return 9
def row():
 events.append('yield:a')
 yield 'a'
 events.append('raise')
 raise ValueError('row failed')
writer=csv.writer(Sink(),lineterminator='\n')
try:writer.writerow(row())
except ValueError as error:print(type(error).__name__,str(error))
print(events)

events=[]
def accept(row):
 events.append(row)
 return len(row)
class Sink:
 @property
 def writerow(self):
  events.append('lookup')
  return accept
def receiver():
 events.append('receiver')
 return Sink()
def argument():
 events.append('argument')
 return ['a','b']
print(receiver().writerow(argument()),events)

import csv,io
sink=io.StringIO()
writer=csv.writer(sink,lineterminator='\n')
print(writer.writerow(*[['a','b']]))
try:writer.writerow()
except TypeError:print('TypeError')
try:writer.writerow([],[])
except TypeError:print('TypeError')
try:writer.writerow(bad=[])
except TypeError:print('TypeError')
print(repr(sink.getvalue()))
